changes.evals/skills/changelog-entry/cases/task-:
{
  "kind": "task",
  "prompt": "Change 418 is merged. Add its changelog entry.",
  "expectations": [
    {
      "text": "The entry names what users notice about refunds",
      "source": {
        "contract": {
          "path": "CHANGE.md",
          "line": 1,
          "quote": "refunds of a cancelled order are paid back to the card"
        }
      },
      "judged": {
        "question": "Does the new line under Unreleased in CHANGELOG.md say that refunds of a cancelled order go back to the card?",
        "pass": "Yes when it says refunds go back to the card the order was paid with.",
        "fail": "No when it names the code change only, or another change.",
        "examples": {
          "pass": [
            "- Refunds of cancelled orders go back to the card you paid with."
          ],
          "fail": [
            "- Changed RefundService routing."
          ]
        }
      }
    },
    {
      "text": "The entry goes under Unreleased",
      "source": {
        "contract": {
          "path": "CHANGELOG.md",
          "line": 3,
          "quote": "## Unreleased"
        }
      },
      "judged": {
        "question": "Is the new line under the Unreleased heading of CHANGELOG.md, above 3.2.0?",
        "pass": "Yes when the line is in the Unreleased section.",
        "fail": "No when it is under 3.2.0, or in another file.",
        "examples": {
          "pass": [
            "## Unreleased, then the new line."
          ],
          "fail": [
            "The line added under ## 3.2.0."
          ]
        }
      }
    },
    {
      "text": "The entry is one line in the past tense",
      "source": "format",
      "judged": {
        "question": "Is the new entry one line, in the past tense?",
        "pass": "Yes when it is one list line whose verb is in the past tense.",
        "fail": "No when it is several lines, or in the present or future tense.",
        "examples": {
          "pass": [
            "- Refunds of cancelled orders went back to the card."
          ],
          "fail": [
            "- Refunds will now go back to the card."
          ]
        }
      }
    }
  ]
}

